package project.init.framework.domain;import lombok.Data;import org.springframework.security.core.GrantedAuthority;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.util.CollectionUtils;import java.util.ArrayList;import java.util.List;@Datapublic class AccessToken {    private String username;    private long expiresAt;    private long issuedAt;    private List<String> roles;    public List<GrantedAuthority> getAuthorities() {        List<GrantedAuthority> authorities = new ArrayList<>();        if (!CollectionUtils.isEmpty(roles)) {            roles.forEach(r -> authorities.add(new SimpleGrantedAuthority(r)));        }        return authorities;    }}